const test = require('node:test');
const assert = require('node:assert/strict');
const { readReturnPath } = require('../return-path.cjs');
test('decodes only at the query parsing layer', () => {
  assert.equal(readReturnPath('?return=%252Fstaff'), '%2Fstaff');
  assert.equal(readReturnPath('return=%25'), '%');
  assert.equal(readReturnPath('return=%2Fstaff%3Fa%3D1'), '/staff?a=1');
  assert.equal(readReturnPath('return=a%2Bb+c'), 'a+b c');
});
test('empty, missing and repeated values', () => {
  assert.equal(readReturnPath('return='), '');
  assert.equal(readReturnPath('x=2'), null);
  assert.equal(readReturnPath(''), null);
  assert.equal(readReturnPath('return=first&return=second'), 'first');
});

